(()=>{'use strict';const $=s=>document.querySelector(s);let lastTrigger;const menu=$('#menu'),nav=$('#navigation');const closeMenu=()=>{nav.dataset.open='false';menu.setAttribute('aria-expanded','false')};menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.dataset.open=String(open)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const dialog=$('#contact-dialog'),form=$('#contact-form');const clearErrors=()=>{for(const id of ['message','contact']){$('#'+id+'-error').textContent='';$('#'+id).removeAttribute('aria-invalid')}$('#form-status').textContent=''};
document.querySelectorAll('[data-open-callback]').forEach(btn=>btn.addEventListener('click',()=>{lastTrigger=btn;form.reset();clearErrors();$('#contact').type='tel';$('#contact').inputMode='tel';$('#contact').autocomplete='tel';$('#vehicle').value=btn.dataset.vehicle||'';$('#message').value=btn.dataset.symptom||btn.dataset.service||'';closeMenu();dialog.showModal();(btn.dataset.symptom?$('#vehicle'):$('#message')).focus()}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('[data-close]').addEventListener('click',()=>d.close());d.addEventListener('close',()=>lastTrigger?.focus());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});
$('#channel')?.addEventListener('change',e=>{const val=e.target.value,input=$('#contact');input.type=val==='email'?'email':val==='tel'?'tel':'text';input.inputMode=val==='email'?'email':val==='tel'?'tel':'text';input.autocomplete=val==='email'?'email':val==='tel'?'tel':'off';input.value='';clearErrors()});
form?.addEventListener('submit',e=>{e.preventDefault();clearErrors();const channel=$('#channel').value,contact=$('#contact').value.trim(),message=$('#message').value.trim();let first;const error=(id,text)=>{$('#'+id+'-error').textContent=text;$('#'+id).setAttribute('aria-invalid','true');first??=$('#'+id)};if(!message)error('message','Опишите, что произошло с автомобилем.');const valid=channel==='tel'?contact.replace(/\D/g,'').length>=10&&contact.replace(/\D/g,'').length<=15:channel==='email'?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact):/^@?[a-zA-Z0-9_]{5,32}$/.test(contact);if(!valid)error('contact',channel==='tel'?'Укажите телефон с кодом страны.':channel==='email'?'Укажите email, например name@example.ru.':'Укажите имя Telegram: от 5 букв, цифр или подчёркиваний.');if(first){first.focus();return}$('#form-status').textContent='Поля заполнены корректно. Это превью: заявка не отправлена, данные не сохранены.'});
document.querySelectorAll('[data-photo]').forEach(btn=>btn.addEventListener('click',()=>{lastTrigger=btn;const d=$('#photo-dialog');d.querySelector('img').src=btn.dataset.photo;d.querySelector('img').alt=btn.dataset.caption;d.querySelector('p').textContent=btn.dataset.caption;d.showModal()}));})();
